'use strict';
const express = require('express');
const bcrypt = require('bcryptjs');
const multer = require('multer');
const path = require('path');
const fs = require('fs');
const https = require('https');
const crypto = require('crypto');
const zlib = require('zlib');
const archiver = require('archiver');
const PDFDocument = require('pdfkit');
const config = require('./config');
const { db } = require('./db');
const H = require('./helpers');

const router = express.Router();
const ROLES = ['ROOT','GURU','KOORDINATOR','CONTRIBUTOR'];
const TANAMAN_STATUS = ['Sehat','Bermasalah','Mati','Berbuah','Panen'];
const DAUN = ['Baik','Menguning','Layu','Rusak','Bercak'];
const BATANG = ['Baik','Lemah','Rusak','Perubahan warna'];
const TANAH = ['Lembap','Normal','Kering','Terlalu basah'];
const ADA = ['Tidak ditemukan','Ditemukan'];
const JENIS_PERAWATAN = ['Penyiraman','Pemupukan','Penyiangan','Pemangkasan','Pengendalian Hama','Pengendalian Penyakit','Pemasangan Penyangga','Pembersihan','Lainnya'];
const STATUS_JADWAL = ['Belum Dilakukan','Berlangsung','Selesai','Dibatalkan'];
const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: config.maxUpload } });

function render403(res) { return res.status(403).render('error', { status:403, message:'Anda tidak memiliki akses ke halaman ini.', title:'Akses Ditolak' }); }
function render404(res) { return res.status(404).render('error', { status:404, message:'Data tidak ditemukan.', title:'Error 404' }); }
function requireLogin(req,res,next){ if(req.user) return next(); return req.path.startsWith('/api/') ? res.status(401).json({success:false,message:'Silakan masuk terlebih dahulu.'}) : res.redirect('/login'); }
function requireRoot(req,res,next){ return req.user?.role === 'ROOT' ? next() : render403(res); }
function getPlant(id){ return db.prepare('SELECT t.*, c.kode_kelas FROM tanaman t LEFT JOIN classes c ON c.id=t.class_id WHERE t.id=? AND t.deleted_at IS NULL').get(id); }
function getRecordWithPlant(table,id){ return db.prepare(`SELECT r.*, t.class_id, t.kode_tanaman, t.nama_tanaman, t.deleted_at AS tanaman_deleted_at FROM ${table} r JOIN tanaman t ON t.id=r.tanaman_id WHERE r.id=? AND r.deleted_at IS NULL`).get(id); }
function classesFor(user){ if(H.perm.isGlobal(user)) return db.prepare("SELECT * FROM classes WHERE status='Aktif' ORDER BY kode_kelas").all(); if(user?.class_id) return db.prepare('SELECT * FROM classes WHERE id=? AND status=\'Aktif\'').all(user.class_id); return []; }
function userClasses(user){ if(user.role==='ROOT') return db.prepare('SELECT * FROM classes ORDER BY kode_kelas').all(); if(user.role==='GURU') return db.prepare("SELECT * FROM classes WHERE status='Aktif' ORDER BY kode_kelas").all(); if(user.role==='KOORDINATOR' && user.class_id) return db.prepare('SELECT * FROM classes WHERE id=?').all(user.class_id); return []; }
function allowedRoles(user){ if(user.role==='ROOT') return ROLES; if(user.role==='GURU') return ['KOORDINATOR','CONTRIBUTOR']; if(user.role==='KOORDINATOR') return ['CONTRIBUTOR']; return []; }
function findUserForEdit(current,id){ const u=db.prepare('SELECT * FROM users WHERE id=? AND deleted_at IS NULL').get(id); if(!u) return null; if(current.role==='KOORDINATOR' && u.class_id!==current.class_id) return null; if(current.role!=='ROOT' && u.role==='ROOT') return null; return u; }
function recordScope(req, table, id){ const row=getRecordWithPlant(table,id); if(!row) return null; if(row.tanaman_deleted_at) return null; const plant=getPlant(row.tanaman_id); if(!plant || !H.perm.canTanaman(req.user,plant)) return null; return {row,plant}; }
function saveFlash(req,type,message){ req.session.flash={type,message}; }

// AUTH
router.get('/login',(req,res)=>{ if(req.user) return res.redirect('/'); const root=db.prepare("SELECT password_hash FROM users WHERE username=? AND role='ROOT' LIMIT 1").get(config.adminUser); return res.render('login',{title:'Masuk',identity:'',error:null,showHint:!!root&&bcrypt.compareSync(config.adminPass,root.password_hash),defUser:config.adminUser,defPass:config.adminPass}); });
router.post('/login',(req,res)=>{ const identity=H.str(req.body.identity).toLowerCase(); const password=String(req.body.password||''); const user=db.prepare("SELECT * FROM users WHERE (lower(username)=? OR lower(email)=?) AND deleted_at IS NULL AND status='Aktif' LIMIT 1").get(identity,identity); if(!user||!bcrypt.compareSync(password,user.password_hash)){ H.audit(req,'login',null,null,'failed'); return res.status(401).render('login',{title:'Masuk',identity,error:'Tidak dapat masuk. Periksa username/email dan password.',showHint:false,defUser:'',defPass:''}); } req.session.userId=user.id; req.session.save(err=>{ if(err){ console.error('[session] save failed:',err); return res.status(500).render('error',{status:500,message:'Session gagal disimpan.',title:'Error 500'});} db.prepare("UPDATE users SET last_login=datetime('now') WHERE id=?").run(user.id); req.user=user; H.audit(req,'login','user',user.id); return res.redirect('/'); }); });
router.post('/logout',(req,res)=>{ if(req.user) H.audit(req,'logout','user',req.user.id); req.session.destroy(()=>res.redirect('/login')); });

// DASHBOARD
router.get('/',requireLogin,(req,res)=>{ const scope=H.perm.scopeIds(req.user); const filter=scope?`AND t.class_id IN (${scope.map(()=>'?').join(',')})`:''; const args=scope||[]; const totals=db.prepare(`SELECT COUNT(*) total, SUM(status='Sehat') sehat, SUM(status='Bermasalah') bermasalah, SUM(status='Mati') mati, SUM(status='Berbuah') berbuah, SUM(status='Panen') panen FROM tanaman t WHERE t.deleted_at IS NULL ${filter}`).get(...args); const avg=db.prepare(`SELECT AVG(p.tinggi_cm) avg FROM pengukuran p JOIN tanaman t ON t.id=p.tanaman_id WHERE p.deleted_at IS NULL AND t.deleted_at IS NULL AND p.tinggi_cm IS NOT NULL ${filter}`).get(...args); const latestPeng=db.prepare(`SELECT p.*,t.kode_tanaman FROM pengamatan p JOIN tanaman t ON t.id=p.tanaman_id WHERE p.deleted_at IS NULL AND t.deleted_at IS NULL ${filter} ORDER BY p.tanggal DESC,p.id DESC LIMIT 6`).all(...args); const latestRaw=db.prepare(`SELECT r.*,t.kode_tanaman FROM perawatan r JOIN tanaman t ON t.id=r.tanaman_id WHERE r.deleted_at IS NULL AND t.deleted_at IS NULL ${filter} ORDER BY r.tanggal DESC,r.id DESC LIMIT 6`).all(...args); const jadwalSql=scope?`SELECT j.*,c.kode_kelas FROM jadwal j JOIN classes c ON c.id=j.class_id WHERE j.deleted_at IS NULL AND j.tanggal>=date('now') AND j.class_id IN (${scope.map(()=>'?').join(',')}) ORDER BY j.tanggal ASC,j.id ASC LIMIT 5`:`SELECT j.*,c.kode_kelas FROM jadwal j JOIN classes c ON c.id=j.class_id WHERE j.deleted_at IS NULL AND j.tanggal>=date('now') ORDER BY j.tanggal ASC,j.id ASC LIMIT 5`; const jadwal=db.prepare(jadwalSql).all(...args); return res.render('dashboard',{title:'Dashboard',totals:{total:totals.total||0,Sehat:totals.sehat||0,Bermasalah:totals.bermasalah||0,Mati:totals.mati||0,Berbuah:totals.berbuah||0,Panen:totals.panen||0},avgTinggi:avg.avg==null?null:Math.round(avg.avg*10)/10,latestPeng,latestRaw,jadwal}); });

// TANAMAN
router.get('/tanaman',requireLogin,(req,res)=>{ const scope=H.perm.scopeIds(req.user); const where=['t.deleted_at IS NULL']; const args=[]; if(scope){where.push(`t.class_id IN (${scope.map(()=>'?').join(',')})`);args.push(...scope);} const q=H.str(req.query.q); const cid=H.parseId(req.query.class_id); const status=H.str(req.query.status); if(q){where.push('(t.kode_tanaman LIKE ? OR t.nama_tanaman LIKE ?)');args.push(`%${q}%`,`%${q}%`);} if(cid){if(scope&&!scope.includes(cid)) return render403(res); where.push('t.class_id=?');args.push(cid);} if(status){if(!TANAMAN_STATUS.includes(status)) return res.status(400).render('error',{status:400,message:'Status tanaman tidak valid.',title:'Error 400'});where.push('t.status=?');args.push(status);} const tanaman=db.prepare(`SELECT t.*,c.kode_kelas FROM tanaman t LEFT JOIN classes c ON c.id=t.class_id WHERE ${where.join(' AND ')} ORDER BY t.kode_tanaman`).all(...args); return res.render('tanaman-list',{title:'Data Tanaman',tanaman,classes:classesFor(req.user),search:q,class_id:cid,status}); });
router.get('/tanaman/baru',requireLogin,(req,res)=>res.render('tanaman-form',{title:'Tambah Tanaman',mode:'create',data:{tanggal_tanam:new Date().toISOString().slice(0,10),status:'Sehat'},error:null,classes:classesFor(req.user)}));
router.post('/tanaman/baru',requireLogin,(req,res)=>{try{const d=req.body;const tanggal=H.parseDate(d.tanggal_tanam,'Tanggal tanam');const classId=H.parseId(d.class_id);if(!H.perm.canCreateTanaman(req.user,classId))return render403(res);const kode=H.str(d.kode_tanaman);const nama=H.str(d.nama_tanaman);if(!kode||!nama)throw new Error('Kode dan nama tanaman wajib diisi.');if(db.prepare('SELECT id FROM tanaman WHERE kode_tanaman=?').get(kode))throw new Error('Kode tanaman sudah dipakai.');const info=db.prepare(`INSERT INTO tanaman(kode_tanaman,nama_tanaman,varietas,tanggal_tanam,class_id,lokasi,posisi,status,catatan,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)`).run(kode,nama,H.str(d.varietas)||null,tanggal,classId,H.str(d.lokasi)||null,H.str(d.posisi)||null,TANAMAN_STATUS.includes(H.str(d.status))?H.str(d.status):'Sehat',H.str(d.catatan)||null,req.user.id);H.audit(req,'create','tanaman',info.lastInsertRowid,'success',null,db.prepare('SELECT * FROM tanaman WHERE id=?').get(info.lastInsertRowid));saveFlash(req,'success','Tanaman berhasil ditambahkan.');return res.redirect('/tanaman/'+info.lastInsertRowid);}catch(e){return res.status(422).render('tanaman-form',{title:'Tambah Tanaman',mode:'create',data:req.body,error:e.message,classes:classesFor(req.user)});}});
router.get('/tanaman/:id',requireLogin,(req,res,next)=>{const t=getPlant(H.parseId(req.params.id));if(!t)return render404(res);if(!H.perm.canTanaman(req.user,t))return render403(res);const pengamatan=db.prepare('SELECT * FROM pengamatan WHERE tanaman_id=? AND deleted_at IS NULL ORDER BY tanggal DESC,id DESC').all(t.id);const pengukuran=db.prepare('SELECT * FROM pengukuran WHERE tanaman_id=? AND deleted_at IS NULL ORDER BY tanggal ASC,id ASC').all(t.id);const perawatan=db.prepare('SELECT * FROM perawatan WHERE tanaman_id=? AND deleted_at IS NULL ORDER BY tanggal DESC,id DESC').all(t.id);const dokumentasi=db.prepare('SELECT * FROM dokumentasi WHERE tanaman_id=? AND deleted_at IS NULL ORDER BY tanggal DESC,id DESC').all(t.id);const timeline=[...pengamatan.map(x=>({tanggal:x.tanggal,tipe:'Pengamatan',teks:x.catatan||('Daun: '+(x.kondisi_daun||'-'))})),...pengukuran.map(x=>({tanggal:x.tanggal,tipe:'Pengukuran',teks:`Tinggi ${x.tinggi_cm??'-'} cm`})),...perawatan.map(x=>({tanggal:x.tanggal,tipe:'Perawatan',teks:x.jenis_kegiatan+(x.keterangan?' — '+x.keterangan:'')})),...dokumentasi.map(x=>({tanggal:x.tanggal,tipe:'Dokumentasi',teks:x.keterangan||x.original_name||x.filename}))].sort((a,b)=>b.tanggal.localeCompare(a.tanggal));const latest=pengukuran.length?pengukuran[pengukuran.length-1]:null;const chartLabels=pengukuran.map(x=>x.tanggal);return res.render('tanaman-detail',{title:t.kode_tanaman,t,pengamatan,pengukuran,perawatan,dokumentasi,timeline,latest,canEdit:H.perm.canEditTanaman(req.user,t),canRecord:H.perm.canEditRecord(req.user,t),chartData:{tinggi:pengukuran.map(x=>x.tinggi_cm),daun:pengukuran.map(x=>x.jumlah_daun),cabang:pengukuran.map(x=>x.jumlah_cabang),bunga:pengukuran.map(x=>x.jumlah_bunga),buah:pengukuran.map(x=>x.jumlah_buah)},chartLabels});});
router.get('/tanaman/:id/edit',requireLogin,(req,res)=>{const t=getPlant(H.parseId(req.params.id));if(!t)return render404(res);if(!H.perm.canEditTanaman(req.user,t))return render403(res);return res.render('tanaman-form',{title:'Ubah Tanaman',mode:'edit',data:t,error:null,classes:classesFor(req.user)});});
router.post('/tanaman/:id/edit',requireLogin,(req,res)=>{const t=getPlant(H.parseId(req.params.id));if(!t)return render404(res);if(!H.perm.canEditTanaman(req.user,t))return render403(res);try{const d=req.body;const tanggal=H.parseDate(d.tanggal_tanam,'Tanggal tanam');const classId=H.parseId(d.class_id);if(!H.perm.canCreateTanaman(req.user,classId))return render403(res);const kode=H.str(d.kode_tanaman),nama=H.str(d.nama_tanaman);if(!kode||!nama)throw new Error('Kode dan nama tanaman wajib diisi.');const conflict=db.prepare('SELECT id FROM tanaman WHERE kode_tanaman=? AND id!=?').get(kode,t.id);if(conflict)throw new Error('Kode tanaman sudah dipakai.');const before={...t};db.prepare(`UPDATE tanaman SET kode_tanaman=?,nama_tanaman=?,varietas=?,tanggal_tanam=?,class_id=?,lokasi=?,posisi=?,status=?,catatan=?,updated_at=datetime('now') WHERE id=?`).run(kode,nama,H.str(d.varietas)||null,tanggal,classId,H.str(d.lokasi)||null,H.str(d.posisi)||null,TANAMAN_STATUS.includes(H.str(d.status))?H.str(d.status):'Sehat',H.str(d.catatan)||null,t.id);const after=db.prepare('SELECT * FROM tanaman WHERE id=?').get(t.id);H.audit(req,'update','tanaman',t.id,'success',before,after);saveFlash(req,'success','Perubahan tanaman disimpan.');return res.redirect('/tanaman/'+t.id);}catch(e){return res.status(422).render('tanaman-form',{title:'Ubah Tanaman',mode:'edit',data:req.body,error:e.message,classes:classesFor(req.user)});}});
router.post('/tanaman/:id/delete',requireLogin,(req,res)=>{const t=getPlant(H.parseId(req.params.id));if(!t)return render404(res);if(!H.perm.canEditTanaman(req.user,t))return render403(res);db.prepare("UPDATE tanaman SET deleted_at=datetime('now'),deleted_by=?,updated_at=datetime('now') WHERE id=?").run(req.user.id,t.id);H.audit(req,'delete','tanaman',t.id);saveFlash(req,'info','Tanaman dipindahkan dari daftar aktif.');return res.redirect('/tanaman');});

