router.get('/pengamatan',requireLogin,(req,res)=>{const scope=H.perm.scopeIds(req.user);const where=['p.deleted_at IS NULL','t.deleted_at IS NULL'];const args=[];if(scope){where.push(`t.class_id IN (${scope.map(()=>'?').join(',')})`);args.push(...scope);}const items=db.prepare(`SELECT p.*,t.kode_tanaman FROM pengamatan p JOIN tanaman t ON t.id=p.tanaman_id WHERE ${where.join(' AND ')} ORDER BY p.tanggal DESC,p.id DESC LIMIT 500`).all(...args);return res.render('pengamatan-list',{title:'Pengamatan',items});});
