router.post('/pengamatan/baru',requireLogin,(req,res)=>{const t=getPlant(H.parseId(req.body.tanaman_id));if(!t)return render404(res);if(!H.perm.canTanaman(req.user,t))return render403(res);try{const d=req.body;const tanggal=H.parseDate(d.tanggal);const info=db.prepare(`INSERT INTO pengamatan(tanaman_id,tanggal,kondisi_daun,kondisi_batang,kondisi_tanah,kondisi_umum,hama,penyakit,kondisi_bunga,kondisi_buah,catatan,pengamat_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)`).run(t.id,tanggal,H.str(d.kondisi_daun)||null,H.str(d.kondisi_batang)||null,H.str(d.kondisi_tanah)||null,H.str(d.kondisi_umum)||null,H.str(d.hama)||null,H.str(d.penyakit)||null,H.str(d.kondisi_bunga)||null,H.str(d.kondisi_buah)||null,H.str(d.catatan)||null,req.user.id);H.audit(req,'create','pengamatan',info.lastInsertRowid);saveFlash(req,'success','Pengamatan disimpan.');return res.redirect('/tanaman/'+t.id);}catch(e){return res.status(422).render('pengamatan-form',{title:'Tambah Pengamatan',t,data:req.body,DAUN,BATANG,TANAH,ADA,error:e.message,mode:'create'});}});
router.get('/pengamatan/:id/edit',requireLogin,(req,res)=>{const scope=recordScope(req,'pengamatan',H.parseId(req.params.id));if(!scope)return render404(res);return res.render('pengamatan-form',{title:'Ubah Pengamatan',t:scope.plant,data:scope.row,DAUN,BATANG,TANAH,ADA,error:null,mode:'edit',id:scope.row.id});});
router.post('/pengamatan/:id/edit',requireLogin,(req,res)=>{const scope=recordScope(req,'pengamatan',H.parseId(req.params.id));if(!scope)return render404(res);try{const d=req.body;const tanggal=H.parseDate(d.tanggal);const before={...scope.row};db.prepare(`UPDATE pengamatan SET tanggal=?,kondisi_daun=?,kondisi_batang=?,kondisi_tanah=?,kondisi_umum=?,hama=?,penyakit=?,kondisi_bunga=?,kondisi_buah=?,catatan=?,updated_at=datetime('now') WHERE id=?`).run(tanggal,H.str(d.kondisi_daun)||null,H.str(d.kondisi_batang)||null,H.str(d.kondisi_tanah)||null,H.str(d.kondisi_umum)||null,H.str(d.hama)||null,H.str(d.penyakit)||null,H.str(d.kondisi_bunga)||null,H.str(d.kondisi_buah)||null,H.str(d.catatan)||null,scope.row.id);H.audit(req,'update','pengamatan',scope.row.id,'success',before,db.prepare('SELECT * FROM pengamatan WHERE id=?').get(scope.row.id));saveFlash(req,'success','Pengamatan diperbarui.');return res.redirect('/tanaman/'+scope.plant.id);}catch(e){return res.status(422).render('pengamatan-form',{title:'Ubah Pengamatan',t:scope.plant,data:req.body,DAUN,BATANG,TANAH,ADA,error:e.message,mode:'edit',id:scope.row.id});}});
router.post('/pengamatan/:id/delete',requireLogin,(req,res)=>{const scope=recordScope(req,'pengamatan',H.parseId(req.params.id));if(!scope)return render404(res);db.prepare("UPDATE pengamatan SET deleted_at=datetime('now'),updated_at=datetime('now') WHERE id=?").run(scope.row.id);H.audit(req,'delete','pengamatan',scope.row.id);saveFlash(req,'info','Pengamatan dihapus.');return res.redirect('/tanaman/'+scope.plant.id);});

