router.get('/perawatan/:id/edit',requireLogin,(req,res)=>{const scope=recordScope(req,'perawatan',H.parseId(req.params.id));if(!scope)return render404(res);return res.render('perawatan-form',{title:'Ubah Perawatan',t:scope.plant,data:scope.row,JENIS:JENIS_PERAWATAN,error:null,mode:'edit',id:scope.row.id});});
router.post('/perawatan/:id/edit',requireLogin,(req,res)=>{const scope=recordScope(req,'perawatan',H.parseId(req.params.id));if(!scope)return render404(res);try{const d=req.body;const jenis=H.str(d.jenis_kegiatan);if(!JENIS_PERAWATAN.includes(jenis))throw new Error('Jenis kegiatan tidak valid.');const before={...scope.row};db.prepare(`UPDATE perawatan SET tanggal=?,jenis_kegiatan=?,petugas=?,keterangan=?,hasil=?,updated_at=datetime('now') WHERE id=?`).run(H.parseDate(d.tanggal),jenis,H.str(d.petugas)||null,H.str(d.keterangan)||null,H.str(d.hasil)||null,scope.row.id);H.audit(req,'update','perawatan',scope.row.id,'success',before,db.prepare('SELECT * FROM perawatan WHERE id=?').get(scope.row.id));saveFlash(req,'success','Perawatan diperbarui.');return res.redirect('/tanaman/'+scope.plant.id);}catch(e){return res.status(422).render('perawatan-form',{title:'Ubah Perawatan',t:scope.plant,data:req.body,JENIS:JENIS_PERAWATAN,error:e.message,mode:'edit',id:scope.row.id});}});
