router.get('/dokumentasi',requireLogin,(req,res)=>{const scope=H.perm.scopeIds(req.user);const where=['d.deleted_at IS NULL','t.deleted_at IS NULL'];const args=[];if(scope){where.push(`t.class_id IN (${scope.map(()=>'?').join(',')})`);args.push(...scope);}const items=db.prepare(`SELECT d.*,t.kode_tanaman FROM dokumentasi d JOIN tanaman t ON t.id=d.tanaman_id WHERE ${where.join(' AND ')} ORDER BY d.tanggal DESC,d.id DESC LIMIT 500`).all(...args);return res.render('dokumentasi-list',{title:'Dokumentasi',items});});
router.get('/dokumentasi/upload',requireLogin,(req,res)=>{const t=getPlant(H.parseId(req.query.tanaman_id));if(!t||!H.perm.canTanaman(req.user,t)){saveFlash(req,'warning','Pilih tanaman yang dapat Anda akses.');return res.redirect('/tanaman');}return res.render('dokumentasi-form',{title:'Upload Dokumentasi',t,data:{tanggal:new Date().toISOString().slice(0,10)},error:null,mode:'create'});});
router.post('/dokumentasi/upload',requireLogin,upload.single('file'),(req,res)=>{const t=getPlant(H.parseId(req.body.tanaman_id));if(!t)return render404(res);if(!H.perm.canTanaman(req.user,t))return render403(res);let saved=null;try{const tanggal=H.parseDate(req.body.tanggal);saved=H.saveImage(req.file);const info=db.prepare(`INSERT INTO dokumentasi(tanaman_id,tanggal,filename,original_name,keterangan,uploaded_by) VALUES(?,?,?,?,?,?)`).run(t.id,tanggal,saved.filename,saved.originalName,H.str(req.body.keterangan)||null,req.user.id);H.audit(req,'upload','dokumentasi',info.lastInsertRowid);saveFlash(req,'success','Foto berhasil diunggah.');return res.redirect('/tanaman/'+t.id);}catch(e){if(saved)H.deleteImage(saved.filename);return res.status(422).render('dokumentasi-form',{title:'Upload Dokumentasi',t,data:req.body,error:e.message,mode:'create'});}});
router.get('/dokumentasi/:id/edit',requireLogin,(req,res)=>{const scope=recordScope(req,'dokumentasi',H.parseId(req.params.id));if(!scope)return render404(res);return res.render('dokumentasi-form',{title:'Ubah Dokumentasi',t:scope.plant,data:scope.row,error:null,mode:'edit',id:scope.row.id});});
router.post('/dokumentasi/:id/edit',requireLogin,upload.single('file'),(req,res)=>{const scope=recordScope(req,'dokumentasi',H.parseId(req.params.id));if(!scope)return render404(res);let newFile=null;try{const d=req.body;const tanggal=H.parseDate(d.tanggal);if(req.file)newFile=H.saveImage(req.file);const oldFile=scope.row.filename;const filename=newFile?newFile.filename:oldFile;const originalName=newFile?newFile.originalName:scope.row.original_name;const before={...scope.row};db.prepare(`UPDATE dokumentasi SET tanggal=?,filename=?,original_name=?,keterangan=?,updated_at=datetime('now') WHERE id=?`).run(tanggal,filename,originalName,H.str(d.keterangan)||null,scope.row.id);if(newFile&&oldFile!==filename)H.deleteImage(oldFile);H.audit(req,'update','dokumentasi',scope.row.id,'success',before,db.prepare('SELECT * FROM dokumentasi WHERE id=?').get(scope.row.id));saveFlash(req,'success','Dokumentasi diperbarui.');return res.redirect('/tanaman/'+scope.plant.id);}catch(e){if(newFile)H.deleteImage(newFile.filename);return res.status(422).render('dokumentasi-form',{title:'Ubah Dokumentasi',t:scope.plant,data:req.body,error:e.message,mode:'edit',id:scope.row.id,existing:scope.row});}});
router.post('/dokumentasi/:id/delete',requireLogin,(req,res)=>{const scope=recordScope(req,'dokumentasi',H.parseId(req.params.id));if(!scope)return render404(res);db.prepare("UPDATE dokumentasi SET deleted_at=datetime('now'),updated_at=datetime('now') WHERE id=?").run(scope.row.id);H.deleteImage(scope.row.filename);H.audit(req,'delete','dokumentasi',scope.row.id);saveFlash(req,'info','Dokumentasi dihapus.');return res.redirect('/tanaman/'+scope.plant.id);});
router.get('/dokumentasi/file/:name',requireLogin,(req,res,next)=>{const name=path.basename(String(req.params.name||''));if(name!==req.params.name)return next({status:400,message:'Nama file tidak valid.'});const row=db.prepare('SELECT d.*,t.class_id FROM dokumentasi d JOIN tanaman t ON t.id=d.tanaman_id WHERE d.filename=? AND d.deleted_at IS NULL AND t.deleted_at IS NULL').get(name);if(!row)return render404(res);const t=getPlant(row.tanaman_id);if(!H.perm.canTanaman(req.user,t))return render403(res);return res.sendFile(path.join(config.uploadDir,row.filename));});

