router.get('/jadwal',requireLogin,(req,res)=>{const scope=H.perm.scopeIds(req.user);const where=['j.deleted_at IS NULL'];const args=[];if(scope){where.push(`j.class_id IN (${scope.map(()=>'?').join(',')})`);args.push(...scope);}const items=db.prepare(`SELECT j.*,c.kode_kelas FROM jadwal j JOIN classes c ON c.id=j.class_id WHERE ${where.join(' AND ')} ORDER BY j.tanggal ASC,j.id ASC`).all(...args);return res.render('jadwal-list',{title:'Jadwal',items});});
