router.post('/jadwal/baru',requireLogin,(req,res)=>{try{const d=req.body;const tanggal=H.parseDate(d.tanggal);const classId=H.parseId(d.class_id);if(!H.perm.canSchedule(req.user,classId))throw new Error('Kelas tidak valid.');const kegiatan=H.str(d.kegiatan);if(!kegiatan)throw new Error('Kegiatan wajib diisi.');const status=STATUS_JADWAL.includes(H.str(d.status))?H.str(d.status):'Belum Dilakukan';const info=db.prepare(`INSERT INTO jadwal(tanggal,class_id,kegiatan,petugas,status,catatan,created_by) VALUES(?,?,?,?,?,?,?)`).run(tanggal,classId,kegiatan,H.str(d.petugas)||null,status,H.str(d.catatan)||null,req.user.id);H.audit(req,'create','jadwal',info.lastInsertRowid);saveFlash(req,'success','Jadwal disimpan.');return res.redirect('/jadwal');}catch(e){return res.status(422).render('jadwal-form',{title:'Tambah Jadwal',data:req.body,error:e.message,classes:classesFor(req.user),STATUS_JADWAL,mode:'create'});}});
router.get('/jadwal/:id/edit',requireLogin,(req,res)=>{const id=H.parseId(req.params.id);const row=db.prepare('SELECT * FROM jadwal WHERE id=? AND deleted_at IS NULL').get(id);if(!row)return render404(res);if(!H.perm.canSchedule(req.user,row.class_id))return render403(res);return res.render('jadwal-form',{title:'Ubah Jadwal',data:row,error:null,classes:classesFor(req.user),STATUS_JADWAL,mode:'edit',id});});
router.post('/jadwal/:id/edit',requireLogin,(req,res)=>{const id=H.parseId(req.params.id);const row=db.prepare('SELECT * FROM jadwal WHERE id=? AND deleted_at IS NULL').get(id);if(!row)return render404(res);if(!H.perm.canSchedule(req.user,row.class_id))return render403(res);try{const d=req.body;const classId=H.parseId(d.class_id);if(!H.perm.canSchedule(req.user,classId))throw new Error('Kelas tidak valid.');const kegiatan=H.str(d.kegiatan);if(!kegiatan)throw new Error('Kegiatan wajib diisi.');const status=STATUS_JADWAL.includes(H.str(d.status))?H.str(d.status):'Belum Dilakukan';const before={...row};db.prepare(`UPDATE jadwal SET tanggal=?,class_id=?,kegiatan=?,petugas=?,status=?,catatan=?,updated_at=datetime('now') WHERE id=?`).run(H.parseDate(d.tanggal),classId,kegiatan,H.str(d.petugas)||null,status,H.str(d.catatan)||null,row.id);H.audit(req,'update','jadwal',row.id,'success',before,db.prepare('SELECT * FROM jadwal WHERE id=?').get(row.id));saveFlash(req,'success','Jadwal diperbarui.');return res.redirect('/jadwal');}catch(e){return res.status(422).render('jadwal-form',{title:'Ubah Jadwal',data:req.body,error:e.message,classes:classesFor(req.user),STATUS_JADWAL,mode:'edit',id});}});
router.post('/jadwal/:id/delete',requireLogin,(req,res)=>{const id=H.parseId(req.params.id);const row=db.prepare('SELECT * FROM jadwal WHERE id=? AND deleted_at IS NULL').get(id);if(!row)return render404(res);if(!H.perm.canSchedule(req.user,row.class_id))return render403(res);db.prepare("UPDATE jadwal SET deleted_at=datetime('now'),updated_at=datetime('now') WHERE id=?").run(row.id);H.audit(req,'delete','jadwal',row.id);saveFlash(req,'info','Jadwal dihapus.');return res.redirect('/jadwal');});

