router.get('/pengguna',requireLogin,(req,res)=>{if(!H.perm.canManageUsers(req.user))return render403(res);const users=req.user.role==='KOORDINATOR'?db.prepare(`SELECT u.*,c.kode_kelas FROM users u LEFT JOIN classes c ON c.id=u.class_id WHERE u.deleted_at IS NULL AND u.class_id=? ORDER BY u.role,u.username`).all(req.user.class_id):db.prepare(`SELECT u.*,c.kode_kelas FROM users u LEFT JOIN classes c ON c.id=u.class_id WHERE u.deleted_at IS NULL ORDER BY u.role,u.username`).all();return res.render('users-list',{title:'Pengguna',users});});
router.get('/pengguna/baru',requireLogin,(req,res)=>{if(!H.perm.canManageUsers(req.user))return render403(res);return res.render('users-form',{title:'Tambah Pengguna',u:null,data:{status:'Aktif'},error:null,classes:userClasses(req.user),roles:allowedRoles(req.user),mode:'create'});});
router.post('/pengguna/baru',requireLogin,(req,res)=>{if(!H.perm.canManageUsers(req.user))return render403(res);const roles=allowedRoles(req.user),classes=userClasses(req.user);try{const d=req.body,role=H.str(d.role),username=H.str(d.username).toLowerCase(),email=H.str(d.email).toLowerCase(),nama=H.str(d.nama),password=String(d.password||'');if(!roles.includes(role))throw new Error('Role tidak diizinkan.');if(!username||!email||!nama||password.length<6)throw new Error('Username, email, nama wajib diisi. Password minimal 6 karakter.');let classId=H.parseId(d.class_id);if(role==='KOORDINATOR'||role==='CONTRIBUTOR'){if(req.user.role==='KOORDINATOR')classId=req.user.class_id;if(!classId||!H.perm.canManageClassUsers(req.user,classId))throw new Error('Kelas tidak valid.');}else classId=null;if(db.prepare('SELECT id FROM users WHERE lower(username)=? OR lower(email)=?').get(username,email))throw new Error('Username atau email sudah dipakai.');const info=db.prepare(`INSERT INTO users(username,email,password_hash,nama,role,class_id,created_by,status) VALUES(?,?,?,?,?,?,?,'Aktif')`).run(username,email,bcrypt.hashSync(password,10),nama,role,classId,req.user.id);H.audit(req,'create_user','user',info.lastInsertRowid);saveFlash(req,'success','Pengguna dibuat.');return res.redirect('/pengguna');}catch(e){return res.status(422).render('users-form',{title:'Tambah Pengguna',u:null,data:req.body,error:e.message,classes,roles,mode:'create'});}});
router.get('/pengguna/:id/edit',requireLogin,(req,res)=>{if(!H.perm.canManageUsers(req.user))return render403(res);const u=findUserForEdit(req.user,H.parseId(req.params.id));if(!u)return render404(res);return res.render('users-form',{title:'Ubah Pengguna',u,data:u,error:null,classes:userClasses(req.user),roles:allowedRoles(req.user),mode:'edit'});});
router.post('/pengguna/:id/edit',requireLogin,(req,res)=>{if(!H.perm.canManageUsers(req.user))return render403(res);const u=findUserForEdit(req.user,H.parseId(req.params.id));if(!u)return render404(res);const roles=allowedRoles(req.user),classes=userClasses(req.user);try{const d=req.body;const email=H.str(d.email).toLowerCase()||u.email;if(email!==u.email&&db.prepare('SELECT id FROM users WHERE lower(email)=? AND id!=?').get(email,u.id))throw new Error('Email sudah dipakai.');const password=String(d.password||'');if(password&&password.length<6)throw new Error('Password minimal 6 karakter.');let role=u.role,classId=u.class_id;if(req.user.role==='ROOT'||req.user.role==='GURU'){if(roles.includes(H.str(d.role)))role=H.str(d.role);else if(req.user.role==='ROOT')throw new Error('Role tidak valid.');if(role==='KOORDINATOR'||role==='CONTRIBUTOR'){classId=H.parseId(d.class_id);if(!classId||!H.perm.canManageClassUsers(req.user,classId))throw new Error('Kelas tidak valid.');}else classId=null;}else if(req.user.role==='KOORDINATOR'){role='CONTRIBUTOR';classId=req.user.class_id;}const status=['Aktif','Nonaktif'].includes(H.str(d.status))?H.str(d.status):u.status;const before={...u};let sql=`UPDATE users SET email=?,nama=?,role=?,class_id=?,status=?,updated_at=datetime('now')`;const values=[email,H.str(d.nama)||u.nama,role,classId,status];if(password){sql+=',password_hash=?';values.push(bcrypt.hashSync(password,10));}sql+=' WHERE id=?';values.push(u.id);db.prepare(sql).run(...values);H.audit(req,'update_user','user',u.id,'success',before,db.prepare('SELECT * FROM users WHERE id=?').get(u.id));saveFlash(req,'success','Pengguna diperbarui.');return res.redirect('/pengguna');}catch(e){return res.status(422).render('users-form',{title:'Ubah Pengguna',u,data:req.body,error:e.message,classes,roles,mode:'edit'});}});
router.post('/pengguna/:id/delete',requireLogin,(req,res)=>{if(!H.perm.canManageUsers(req.user))return render403(res);const u=findUserForEdit(req.user,H.parseId(req.params.id));if(!u)return render404(res);if(u.role==='ROOT')return render403(res);db.prepare("UPDATE users SET deleted_at=datetime('now'),deleted_by=?,status='Nonaktif',updated_at=datetime('now') WHERE id=?").run(req.user.id,u.id);H.audit(req,'delete_user','user',u.id);saveFlash(req,'info','Pengguna dinonaktifkan.');return res.redirect('/pengguna');});

