router.post('/kelas/baru',requireLogin,requireRoot,(req,res)=>{const kode=H.str(req.body.kode_kelas).toUpperCase(),nama=H.str(req.body.nama_kelas),tingkat=H.str(req.body.tingkat)||'X';if(!kode||!nama){saveFlash(req,'danger','Kode dan nama kelas wajib diisi.');return res.redirect('/kelas');}if(db.prepare('SELECT id FROM classes WHERE kode_kelas=?').get(kode)){saveFlash(req,'danger','Kode kelas sudah ada.');return res.redirect('/kelas');}const info=db.prepare('INSERT INTO classes(kode_kelas,nama_kelas,tingkat) VALUES(?,?,?)').run(kode,nama,tingkat);H.audit(req,'create','class',info.lastInsertRowid);saveFlash(req,'success','Kelas ditambahkan.');return res.redirect('/kelas');});
router.post('/kelas/:id/toggle',requireLogin,requireRoot,(req,res)=>{const id=H.parseId(req.params.id),c=db.prepare('SELECT * FROM classes WHERE id=?').get(id);if(!c)return render404(res);const status=c.status==='Aktif'?'Nonaktif':'Aktif';db.prepare("UPDATE classes SET status=?,updated_at=datetime('now') WHERE id=?").run(status,c.id);H.audit(req,'update','class',c.id);saveFlash(req,'success',`Kelas ${c.kode_kelas} sekarang ${status}.`);return res.redirect('/kelas');});

