router.get('/laporan',requireLogin,(req,res)=>res.render('laporan',{title:'Laporan PDF',classes:classesFor(req.user)}));
router.get('/laporan/pdf',requireLogin,(req,res,next)=>{try{const classId=H.parseId(req.query.class_id),plantId=H.parseId(req.query.tanaman_id);const dari=req.query.dari?H.parseDate(req.query.dari,'Dari'):null,sampai=req.query.sampai?H.parseDate(req.query.sampai,'Sampai'):null;if(dari&&sampai&&dari>sampai)throw new Error('Periode tidak valid: tanggal Dari lebih besar dari Sampai.');let kelas=null;let plant=null;if(classId){if(!H.perm.canClass(req.user,classId))return render403(res);kelas=db.prepare('SELECT * FROM classes WHERE id=?').get(classId);if(!kelas)throw new Error('Kelas tidak ditemukan.');}else if(!H.perm.isGlobal(req.user)&&req.user.class_id)kelas=db.prepare('SELECT * FROM classes WHERE id=?').get(req.user.class_id);if(plantId){plant=getPlant(plantId);if(!plant)return render404(res);if(!H.perm.canTanaman(req.user,plant))return render403(res);}const build=(table)=>{const where=[`${table}.deleted_at IS NULL`,'t.deleted_at IS NULL'];const args=[];if(plant){where.push(`${table}.tanaman_id=?`);args.push(plant.id);}else if(kelas){where.push('t.class_id=?');args.push(kelas.id);}if(dari){where.push(`${table}.tanggal>=?`);args.push(dari);}if(sampai){where.push(`${table}.tanggal<=?`);args.push(sampai);}return db.prepare(`SELECT ${table}.* FROM ${table} JOIN tanaman t ON t.id=${table}.tanaman_id WHERE ${where.join(' AND ')} ORDER BY ${table}.tanggal ASC,${table}.id ASC`).all(...args);};const data={pengamatan:build('pengamatan'),pengukuran:build('pengukuran'),perawatan:build('perawatan'),dokumentasi:build('dokumentasi')};H.audit(req,'generate_report','laporan');res.setHeader('Content-Type','application/pdf');res.setHeader('Content-Disposition',`attachment; filename="tomat-grow-laporan-${new Date().toISOString().slice(0,10)}.pdf"`);const doc=new PDFDocument({size:'A4',margin:48,bufferPages:true});doc.pipe(res);doc.fillColor('#1f5f3f').fontSize(20).text('TOMAT GROW',{align:'center'});doc.fillColor('#555').fontSize(10).text('Monitoring Tanaman Tomat',{align:'center'});doc.fillColor('#777').fontSize(9).text(config.schoolName,{align:'center'});doc.moveDown();doc.fillColor('#222').fontSize(9).text(`Kelas: ${kelas?kelas.kode_kelas:'Semua Kelas'}   Periode: ${dari||'-'} s.d. ${sampai||'-'}`);if(plant){doc.moveDown();doc.fontSize(12).fillColor('#1f5f3f').text('Identitas Tanaman');doc.fontSize(9).fillColor('#222').text(`Kode: ${plant.kode_tanaman} | Nama: ${plant.nama_tanaman} | Varietas: ${plant.varietas||'-'}`);doc.text(`Tanggal tanam: ${plant.tanggal_tanam} | Lokasi: ${plant.lokasi||'-'} | Status: ${plant.status}`);}function section(title){doc.moveDown();doc.fillColor('#1f5f3f').fontSize(12).text(title);doc.fillColor('#222').fontSize(8);}function table(headers,rows){const left=48,width=doc.page.width-96,cw=width/headers.length;let y=doc.y;doc.fillColor('#1f5f3f').fontSize(8);headers.forEach((h,i)=>doc.text(String(h),left+i*cw,y,{width:cw}));y+=13;doc.fillColor('#222');for(const row of rows){if(y>doc.page.height-65){doc.addPage();y=48;}row.forEach((v,i)=>doc.text(String(v??'-').slice(0,55),left+i*cw,y,{width:cw}));y+=13;}doc.y=y+3;}if(data.pengukuran.length){section('Riwayat Pengukuran');table(['Tanggal','Tinggi','Daun','Cabang','Bunga','Buah'],data.pengukuran.map(r=>[r.tanggal,r.tinggi_cm??'-',r.jumlah_daun??'-',r.jumlah_cabang??'-',r.jumlah_bunga??'-',r.jumlah_buah??'-']));}if(data.pengamatan.length){section('Riwayat Pengamatan');table(['Tanggal','Daun','Batang','Tanah','Hama','Penyakit'],data.pengamatan.map(r=>[r.tanggal,r.kondisi_daun||'-',r.kondisi_batang||'-',r.kondisi_tanah||'-',r.hama||'-',r.penyakit||'-']));}if(data.perawatan.length){section('Riwayat Perawatan');table(['Tanggal','Jenis','Petugas','Keterangan'],data.perawatan.map(r=>[r.tanggal,r.jenis_kegiatan,r.petugas||'-',(r.keterangan||'-').slice(0,40)]));}if(data.dokumentasi.length){section('Dokumentasi');table(['Tanggal','File','Keterangan'],data.dokumentasi.map(r=>[r.tanggal,r.original_name||r.filename,(r.keterangan||'-').slice(0,45)]));}if(!plant&&!data.pengukuran.length&&!data.pengamatan.length&&!data.perawatan.length&&!data.dokumentasi.length){doc.moveDown().fillColor('#222').fontSize(10).text('Belum ada data untuk filter yang dipilih.');}const range=doc.bufferedPageRange();for(let i=0;i<range.count;i++){doc.switchToPage(range.start+i);doc.fontSize(8).fillColor('#888').text(`TOMAT GROW v${config.version}`,48,doc.page.height-32,{width:300}).text(`Halaman ${i+1}`,doc.page.width-100,doc.page.height-32,{width:50,align:'right'});}doc.end();}catch(e){next(e);}});

// BACKUP
function stamp(){const d=new Date();const p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}_${p(d.getHours())}-${p(d.getMinutes())}-${p(d.getSeconds())}-${String(d.getMilliseconds()).padStart(3,'0')}`;}
function gzip(src,dst){return new Promise((resolve,reject)=>{const input=fs.createReadStream(src),output=fs.createWriteStream(dst);input.on('error',reject);output.on('error',reject);output.on('finish',resolve);input.pipe(zlib.createGzip({level:9})).pipe(output);});}
function archiveUploads(src,out){return new Promise((resolve,reject)=>{const output=fs.createWriteStream(out);const ar=archiver('tar',{gzip:true});output.on('close',resolve);output.on('error',reject);ar.on('error',reject);ar.pipe(output);if(fs.existsSync(src))ar.directory(src,'uploads');ar.finalize();});}
function sha(file){return crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');}
function sendTelegram(folder){if(!config.tgToken||!config.tgChat)return Promise.resolve(['SKIPPED','Telegram tidak dikonfigurasi.']);const file=path.join(folder,'database.sqlite.gz');const bodyFile=fs.readFileSync(file);const boundary='----TG'+crypto.randomBytes(10).toString('hex');const head=Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="chat_id"\r\n\r\n${config.tgChat}\r\n--${boundary}\r\nContent-Disposition: form-data; name="caption"\r\n\r\nBackup TOMAT GROW ${path.basename(folder)}\r\n--${boundary}\r\nContent-Disposition: form-data; name="document"; filename="database.sqlite.gz"\r\nContent-Type: application/gzip\r\n\r\n`);const tail=Buffer.from(`\r\n--${boundary}--\r\n`);const body=Buffer.concat([head,bodyFile,tail]);return new Promise(resolve=>{const r=https.request({method:'POST',hostname:'api.telegram.org',path:`/bot${config.tgToken}/sendDocument`,headers:{'Content-Type':`multipart/form-data; boundary=${boundary}`,'Content-Length':body.length}},res=>{let txt='';res.on('data',c=>txt+=c);res.on('end',()=>{try{const j=JSON.parse(txt);resolve(j.ok?['SUCCESS','Terkirim.']:['FAILED','Telegram menolak permintaan.']);}catch{resolve(['FAILED','Response Telegram tidak valid.']);}});});r.on('error',e=>resolve(['FAILED',e.message.slice(0,120)]));r.write(body);r.end();});}
async function createBackup(triggeredBy){const folder=stamp(),outDir=path.join(config.backupDir,folder);fs.mkdirSync(outDir,{recursive:true});try{const temp=path.join(outDir,'_snapshot.sqlite');db.prepare('VACUUM INTO ?').run(temp);await gzip(temp,path.join(outDir,'database.sqlite.gz'));fs.unlinkSync(temp);await archiveUploads(config.uploadDir,path.join(outDir,'uploads.tar.gz'));const checksum=sha(path.join(outDir,'database.sqlite.gz'));fs.writeFileSync(path.join(outDir,'manifest.json'),JSON.stringify({app:'TOMAT GROW',version:config.version,timestamp:folder,checksum,created_by:triggeredBy},null,2));const size=['database.sqlite.gz','uploads.tar.gz','manifest.json'].reduce((sum,n)=>sum+fs.statSync(path.join(outDir,n)).size,0);const info=db.prepare(`INSERT INTO backup_logs(folder,size_bytes,checksum,status,telegram_status,triggered_by) VALUES(?,?,?,'SUCCESS','PENDING',?)`).run(folder,size,checksum,triggeredBy);const [tgStatus,tgMessage]=await sendTelegram(outDir);db.prepare('UPDATE backup_logs SET telegram_status=?,message=? WHERE id=?').run(tgStatus,tgMessage,info.lastInsertRowid);return {success:true,folder,size,tgStatus,tgMessage};}catch(e){db.prepare(`INSERT INTO backup_logs(folder,status,message,telegram_status,triggered_by) VALUES(?,'FAILED',?,'SKIPPED',?)`).run(folder,String(e.message).slice(0,400),triggeredBy);return {success:false,error:e.message};}}
router.get('/backup',requireLogin,requireRoot,(req,res)=>{let folders=[];try{folders=fs.readdirSync(config.backupDir,{withFileTypes:true}).filter(x=>x.isDirectory()).map(x=>x.name).sort().reverse();}catch(_){}const logs=db.prepare('SELECT * FROM backup_logs ORDER BY timestamp DESC,id DESC LIMIT 100').all();return res.render('backup',{title:'Backup',folders,logs});});
router.post('/backup/buat',requireLogin,requireRoot,async(req,res)=>{const r=await createBackup(req.user.id);H.audit(req,'backup','system',null,r.success?'success':'failed');saveFlash(req,r.success?'success':'danger',r.success?`Backup ${r.folder} berhasil dibuat.${r.tgStatus==='SUCCESS'?' Terkirim ke Telegram.':''}`:`Backup gagal: ${r.error}`);return res.redirect('/backup');});
router.post('/backup/restore',requireLogin,requireRoot,async(req,res)=>{const folder=path.basename(H.str(req.body.folder));if(!folder||folder==='.'||folder==='..'||H.str(req.body.confirm)!=='RESTORE'){saveFlash(req,'danger','Folder atau konfirmasi restore tidak valid.');return res.redirect('/backup');}const dir=path.join(config.backupDir,folder),gz=path.join(dir,'database.sqlite.gz'),manifest=path.join(dir,'manifest.json');if(!fs.existsSync(gz)){saveFlash(req,'danger','File database backup tidak ditemukan.');return res.redirect('/backup');}try{if(fs.existsSync(manifest)){const meta=JSON.parse(fs.readFileSync(manifest,'utf8'));if(meta.checksum&&meta.checksum!==sha(gz))throw new Error('Checksum backup tidak cocok.');}const temp=path.join(config.backupDir,`.restore-${Date.now()}.sqlite`);await new Promise((resolve,reject)=>{const input=fs.createReadStream(gz),out=fs.createWriteStream(temp),gun=zlib.createGunzip();input.on('error',reject);out.on('error',reject);out.on('finish',resolve);input.pipe(gun).pipe(out);});db.pragma('wal_checkpoint(TRUNCATE)');db.close();for(const suffix of ['','-wal','-shm']){const p=config.dbFile+suffix;try{if(fs.existsSync(p))fs.unlinkSync(p);}catch(_){} }fs.copyFileSync(temp,config.dbFile);fs.unlinkSync(temp);return res.send('<!doctype html><html lang="id"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Restore selesai</title><body style="font-family:Arial,sans-serif;padding:40px;background:#f8faf9;color:#111827"><h1>Restore selesai</h1><p>Database berhasil dipulihkan. Restart server TOMAT GROW dari Pterodactyl sebelum digunakan kembali.</p></body></html>');}catch(e){console.error('[restore]',e);return res.status(500).render('error',{status:500,message:`Restore gagal: ${e.message}`,title:'Restore Gagal'});}});

// HEALTH
router.get('/health',(req,res)=>{const state={application:'OK',database:'OK',storage:'OK'};try{db.prepare('SELECT 1').get();}catch(_){state.database='FAIL';}try{fs.mkdirSync(config.backupDir,{recursive:true});const p=path.join(config.backupDir,'.probe');fs.writeFileSync(p,'ok');fs.unlinkSync(p);}catch(_){state.storage='FAIL';}const status=Object.values(state).every(x=>x==='OK')?200:500;return res.status(status).json(state);});
router.get('/health/dashboard',requireLogin,requireRoot,(req,res)=>{const lastBackup=db.prepare('SELECT * FROM backup_logs ORDER BY timestamp DESC,id DESC LIMIT 1').get();let free=0,total=0;try{const s=fs.statfsSync(config.backupDir);free=s.bfree*s.bsize;total=s.blocks*s.bsize;}catch(_){}let dbStatus='OK';try{db.prepare('SELECT 1').get();}catch(_){dbStatus='FAIL';}return res.render('health',{title:'System Health',lastBackup,diskFreeGb:(free/1024**3).toFixed(1),diskTotalGb:(total/1024**3).toFixed(1),tgStatus:config.tgToken&&config.tgChat?'Configured':'Not configured',dbStatus});});

module.exports = router;
